SELECT ?film ?filmLabel ?value
WHERE {
  ?film wdt:P57 wd:Q3772;
        wdt:P2998 ?gross.
  ?gross wikibase:quantityAmount ?value.
  ?film rdfs:label ?filmLabel.
  FILTER (LANG(?filmLabel) = 'en').
}
ORDER BY DESC(?value)
LIMIT 5

